// Mount the setup wizard (GET + POST /setup)
const setupApp = new Hono<{ Bindings: Env }>();
setupApp.get("/", (c) => {
  const { sub } = createSetupApp(c.env);
  return sub.fetch(c.req.raw, c.env);
});
setupApp.post("/", (c) => {
  const { sub } = createSetupApp(c.env);
  return sub.fetch(c.req.raw, c.env);
});

// Delegate /setup/* to the setup sub-app
app.route("/setup", createSetupRoutes());

function createSetupRoutes(): Hono<{ Bindings: Env }> {
  const r = new Hono<{ Bindings: Env }>();
  r.all("/*", async (c) => {
    const setupSub = createSetupApp(c.env);
    // Re-create the URL with /setup stripped for the sub-app
    const url = new URL(c.req.url);
    url.pathname = url.pathname.replace(/^\/setup/, "") || "/";
    const rewritten = new Request(url.toString(), c.req.raw);
    return setupSub.fetch(rewritten);
  });
  return r;
}
